import { useCallback } from 'react';
import { useGetConfirmUserMutation } from '~/entities/intro/api/use-get-confirm-user-mutation';
import { ConfirmUserResponse } from '~/entities/pin/api/dtos/types';
import { PIN_CONSTANTS } from '~/entities/pin/lib/constants';
import { UserParams } from '~/entities/user/api/dtos/types';
import { UserStatus } from '~/shared/api/dtos/enums';
import { useMaxFailureHandler } from './use-max-failure-handler';

type HandleUserStatusParams = CheckMemberStatusParams & {
  response: ConfirmUserResponse;
};

type CheckMemberStatusParams = {
  cstmrNo: string;
  account: string;
  onBioLogin?: () => void | Promise<void>;
  onEasyLogin?: () => void | Promise<void>;
  onExistingMember?: () => void | Promise<void>;
  onExistingMemberAddWalletRequest?: () => void | Promise<void>;
  onNonMember?: () => void | Promise<void>;
};

type StatusHandler = () => void | Promise<void>;
type StatusHandlers = Record<string, StatusHandler | undefined>;

export const useCheckMemberStatus = () => {
  const { mutateAsync: getConfirmUser } = useGetConfirmUserMutation();
  const { handleMaxFailure } = useMaxFailureHandler();

  const handleUserStatus = useCallback(
    async ({
      response,
      onBioLogin,
      onEasyLogin,
      onExistingMember,
      onExistingMemberAddWalletRequest,
      onNonMember,
    }: HandleUserStatusParams) => {
      const statusHandlers: StatusHandlers = {
        [UserStatus.생체로그인]: onBioLogin ?? onExistingMember,
        [UserStatus.간편로그인]: onEasyLogin ?? onExistingMemberAddWalletRequest ?? onExistingMember,
        default: onNonMember,
      };

      const handler =
        response.result !== null && response.result !== undefined && statusHandlers[response.result]
          ? statusHandlers[response.result]
          : statusHandlers.default;

      await handler?.();
    },
    [],
  );

  const checkMemberStatus = useCallback(
    async (props: CheckMemberStatusParams) => {
      const reqData: Partial<UserParams> = { cstmrNo: props.cstmrNo, account: props.account };

      try {
        const response: ConfirmUserResponse = await getConfirmUser(reqData);

        if (response.failrCo > PIN_CONSTANTS.MAX_INCORRECT_COUNT) {
          handleMaxFailure();
          return null;
        }

        await handleUserStatus({
          response,
          ...props,
        });

        return response;
      } catch (error) {
        console.error('Error in checkMemberStatus:', error);
        handleMaxFailure();
        return null;
      }
    },
    [handleUserStatus, getConfirmUser, handleMaxFailure],
  );

  return { checkMemberStatus };
};
