import React, { useCallback, useEffect } from 'react';
import { useShallow } from 'zustand/react/shallow';
import { useStore } from '~/app/store/store';
import { SuperAppEncData } from '~/entities/super-app/model/types';
import { useInboundSuperAppCommandHandler } from '~/shared/lib/hooks/super-app/use-inbound-super-app-command-handler';
import { useSendSuperAppCommand } from '~/shared/lib/hooks/super-app/use-send-super-app-command';
import { Splash } from '~/widgets/splash/splash';
import { useGetRouterState } from '~/entities/exchange/lib/use-get-router-state';
import { SuperAppCommandOutbound, SuperAppResultCode } from '~/shared/api/dtos/enums';
import { IS_MOCK_PHASE, TEST_INTRO } from '~/shared/config/environment';
import { devNotiBar } from '~/shared/lib';
import { useNavigate } from '~/shared/lib/hooks';
import { RsaOaep } from '~/shared/lib/utils/rsa-oaep';
import { PATHS } from '~/shared/routes/paths';

export const IntroPage = React.memo(() => {
  const { navigate } = useNavigate();
  const { routerState: state } = useGetRouterState<SuperAppEncData>();
  const { decryptText } = RsaOaep();
  const [resetAuth, clearSuperAppData] = useStore(
    useShallow((s) => [s.authSlice.resetAuth, s.superAppSlice.clearSuperAppData]),
  );
  const { handleInboundSuperAppCommand } = useInboundSuperAppCommandHandler();
  const { sendSuperAppCommand } = useSendSuperAppCommand();
  const initialize = useCallback(async () => {
    // 히스토리 초기화
    if (window.history && window.history.pushState) {
      window.history.pushState(null, '', window.location.pathname);
      window.onpopstate = () => {
        window.history.pushState(null, '', window.location.pathname);
      };
    }

    clearSuperAppData();
    resetAuth();

    if (IS_MOCK_PHASE) {
      navigate(PATHS.home);
      return;
    }

    if (TEST_INTRO === true && !state?.encData && !state?.cstmrNo) {
      navigate(PATHS.superAppSample);
      return;
    }

    if (state?.encData) {
      const decryptedData = await decryptText(state);
      await devNotiBar(`WalletApp 인바운드 명령 처리 -> ${decryptedData.command}`, 0, 2000);
      await handleInboundSuperAppCommand(decryptedData);
    } else {
      await sendSuperAppCommand({
        command: SuperAppCommandOutbound.슈퍼앱_에러콜백,
        resultCode: SuperAppResultCode.잘못된요청,
      });
    }
  }, [state.encData]);

  useEffect(() => {
    initialize();
  }, [initialize]);

  return <Splash />;
});

IntroPage.displayName = 'IntroPage';
