import { useCallback } from 'react';
import { SuperAppEncData } from '~/entities/super-app/model/types';
import { useSendSuperAppCommand } from '~/shared/lib/hooks/super-app/use-send-super-app-command';
import { setUserRes } from '~/entities/user/api/use-get-cstmr-query';
import { SuperAppCommandOutbound, SuperAppResultCode } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { useAlertDialog } from '~/shared/lib/hooks/use-alert-dialog';
import { useCheckMemberStatus } from '~/shared/lib/hooks/use-check-member-status';
import { useNavigate } from '~/shared/lib/hooks/use-navigate';
import { PATHS } from '~/shared/routes/paths';

const INBOUND_LOGIN = 'S';
const INBOUND_ADD_WALLET = 'W';
const INBOUND_PAYMENT = 'P';
const INBOUND_CREATE_WALLET = 'C';
const OUTBOUND_CREATE_WALLET = 'C' as SuperAppCommandOutbound;
const OUTBOUND_ERROR = 'E' as SuperAppCommandOutbound;
const RESULT_CODE_UNAUTHORIZED = '401' as SuperAppResultCode;
const VERIFICATION_NEW_USER = 'NewUser';
const VERIFICATION_EXISTING_USER = 'ExistingUser';

export const useInboundSuperAppCommandHandler = () => {
  const { navigate } = useNavigate();
  const { openAlertDialog } = useAlertDialog();
  const { sendSuperAppCommand } = useSendSuperAppCommand();
  const { checkMemberStatus } = useCheckMemberStatus();

  const syncInboundUser = useCallback((reqData: SuperAppEncData) => {
    setUserRes((prev) => ({
      ...prev,
      tbCstmrMastr: {
        ...prev.tbCstmrMastr,
        ...reqData,
        cstmrNo: reqData.cstmrNo ?? '',
        acnutno: reqData.acnutno ?? reqData.account ?? '',
      },
    }));
  }, []);

  const handleNonMember = useCallback(
    (reqData: SuperAppEncData) => {
      openAlertDialog({
        message: i18n.t('text:createUserConfirmText'),
        buttonLabel: [i18n.t('cancel'), i18n.t('confirm')],
        onConfirmClick: async () => {
          await sendSuperAppCommand({
            command: OUTBOUND_CREATE_WALLET,
            data: reqData,
            resultCode: RESULT_CODE_UNAUTHORIZED,
          });
        },
        onCancelClick: async () => {
          await sendSuperAppCommand({
            command: OUTBOUND_ERROR,
            data: reqData,
            resultCode: RESULT_CODE_UNAUTHORIZED,
          });
        },
      });
      return false;
    },
    [openAlertDialog, sendSuperAppCommand],
  );

  const handleExistingMember = useCallback(
    (reqData: SuperAppEncData) => {
      navigate(PATHS.pin.login, { replace: true, state: { ...reqData } });
      return true;
    },
    [navigate],
  );

  const handleExistingMemberAddWalletRequest = useCallback(
    (reqData: SuperAppEncData) => {
      navigate(PATHS.mobileVerification, {
        replace: true,
        state: {
          ...reqData,
          command: INBOUND_ADD_WALLET,
          verificationType: VERIFICATION_EXISTING_USER,
        },
      });

      return true;
    },
    [navigate],
  );

  const handleInboundSuperAppCommand = useCallback(
    async (reqData: SuperAppEncData) => {
      try {
        switch (reqData.command) {
          case INBOUND_LOGIN:
          case INBOUND_PAYMENT: {
            return new Promise((resolve) => {
              if (!reqData.cstmrNo || !reqData.account) {
                throw new Error('cstmrNo or acnutno is required');
              }

              syncInboundUser(reqData);

              checkMemberStatus({
                cstmrNo: reqData.cstmrNo,
                account: reqData.account,
                onBioLogin: () => {
                  const result = handleExistingMember(reqData);
                  resolve(result);
                },
                onEasyLogin: () => {
                  const result = handleExistingMemberAddWalletRequest(reqData);
                  resolve(result);
                },
                onNonMember: () => {
                  const result = handleNonMember(reqData);
                  resolve(result);
                },
              });
            });
          }

          case INBOUND_CREATE_WALLET:
            return new Promise((resolve) => {
              navigate(PATHS.mobileVerification, {
                replace: true,
                state: {
                  ...reqData,
                  verificationType: VERIFICATION_NEW_USER,
                },
              });
              resolve(true);
            });

          case INBOUND_ADD_WALLET:
            return new Promise((resolve) => {
              if (!reqData.cstmrNo || !reqData.account) {
                throw new Error('cstmrNo or acnutno is required');
              }

              syncInboundUser(reqData);

              checkMemberStatus({
                cstmrNo: reqData.cstmrNo,
                account: reqData.account,
                onExistingMemberAddWalletRequest: () => {
                  const result = handleExistingMemberAddWalletRequest(reqData);
                  resolve(result);
                },
                onNonMember: () => {
                  const result = handleNonMember(reqData);
                  resolve(result);
                },
              });
            });

          default:
            openAlertDialog({
              title: '처리되지 않은 인바운드 명령',
              message: reqData,
            });
            return Promise.resolve(false);
        }
      } catch (error) {
        console.error(error);
        openAlertDialog({
          title: 'useInboundSuperAppCommandHandler 에러',
          message: reqData,
        });
        return Promise.resolve(false);
      }
    },
    [
      checkMemberStatus,
      handleExistingMember,
      handleExistingMemberAddWalletRequest,
      handleNonMember,
      navigate,
      openAlertDialog,
      syncInboundUser,
    ],
  );

  return { handleInboundSuperAppCommand };
};
